    # output values can originate in unrelated columns. Give a deterministic
    # order for those mixed values.
    if a is None or b is None:
        return 0 if a is b else (-1 if a is None else 1)
    if type(a) in (int, float) and type(b) in (int, float):
        return (a > b) - (a < b)
    if type(a) is type(b):
        return (a > b) - (a < b)
    return (str(type(a)) > str(type(b))) - (str(type(a)) < str(type(b)))


