"""Expression evaluation helpers for minisql.

AST nodes are dictionaries (see ``eval_expr``); keeping this module independent
of the parser makes the execution semantics easy to reuse for rows and groups.
"""
import math
import re
from decimal import Decimal, ROUND_HALF_UP


AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}
SCALARS = {"LOWER", "UPPER", "LENGTH", "ABS", "ROUND", "COALESCE"}


def _error(message):
    # Imported lazily because __init__ imports the execution modules.
    from . import QueryError
    raise QueryError(message)


def truth(value):
    """SQL truth conversion, rejecting values that are not booleans."""
    if value is None or isinstance(value, bool):
        return value
    _error("logical operators require booleans")


def _compare(a, b, op):
    if a is None or b is None:
        return None
    if isinstance(a, bool) or isinstance(b, bool):
        if not (isinstance(a, bool) and isinstance(b, bool)):
            _error("cannot compare boolean and non-boolean values")
    elif isinstance(a, (int, float)) and isinstance(b, (int, float)):
        pass
    elif isinstance(a, str) and isinstance(b, str):
        pass
    else:
        _error("incompatible values in comparison")
    try:
        return {"=": lambda: a == b, "!=": lambda: a != b,
                "<>": lambda: a != b, "<": lambda: a < b,
                "<=": lambda: a <= b, ">": lambda: a > b,
                ">=": lambda: a >= b}[op]()
    except KeyError:
        _error("unknown comparison operator: " + str(op))


def _round(value, places=None):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        _error("ROUND requires a number")
    places = 0 if places is None else places
    if isinstance(places, bool) or not isinstance(places, int):
        _error("ROUND precision must be an integer")
    # Decimal(str(...)) avoids binary tie surprises and ROUND_HALF_UP is away
    # from zero after sign handling via quantize.
    quantum = Decimal(1).scaleb(-places)
    result = Decimal(str(value)).copy_abs().quantize(quantum, rounding=ROUND_HALF_UP)
    if value < 0:
        result = -result
    if places == 0:
        return int(result)
    return float(result)


def _aggregate(name, args, rows, headers):
    name = name.upper()
    if name == "COUNT" and len(args) == 1 and args[0] == "*":
        return len(rows)
    if len(args) != 1 or args[0] == "*":
        _error(name + " requires exactly one expression")
    vals = [eval_expr(args[0], row, headers) for row in rows]
    vals = [v for v in vals if v is not None]
    if name == "COUNT":
        return len(vals)
    if not vals:
        return None
    if name in ("SUM", "AVG"):
        for v in vals:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                _error(name + " requires numeric values")
        return sum(vals) if name == "SUM" else float(sum(vals) / len(vals))
    for v in vals[1:]:
        _compare(vals[0], v, "=")
    return min(vals) if name == "MIN" else max(vals)


