            return x.lower() if name == "LOWER" else x.upper()
        if name == "LENGTH":
            if not isinstance(x, str): _error("LENGTH requires a string")
            return len(x)
        if name == "ABS":
            if isinstance(x, bool) or not isinstance(x, (int, float)): _error("ABS requires a number")
            return abs(x)
        return _round(x, values[1] if len(values) == 2 else None)
    if typ == "isnull":
        result = eval_expr(node["expr"], row, headers, group) is None
        return not result if node.get("negated") else result
    if typ == "in":
        x = eval_expr(node["expr"], row, headers, group)
        vals = [eval_expr(a, row, headers, group) for a in node.get("items", [])]
        if x is None: result = None
        elif any(v is not None and _compare(x, v, "=") for v in vals): result = True
        elif any(v is None for v in vals): result = None
        else: result = False
        return (not result if result is not None else None) if node.get("negated") else result
    if typ == "between":
        x = eval_expr(node["expr"], row, headers, group)
        lo = eval_expr(node["low"], row, headers, group)
        hi = eval_expr(node["high"], row, headers, group)
        result = None if x is None or lo is None or hi is None else (_compare(lo, x, "<=") and _compare(x, hi, "<="))
        return (not result if result is not None else None) if node.get("negated") else result
    if typ == "unary":
        op = str(node["op"]).upper(); v = eval_expr(node["expr"], row, headers, group)
        if op == "NOT":
            v = truth(v); return None if v is None else not v
        if v is None: return None
        if op == "-":
            if isinstance(v, bool) or not isinstance(v, (int, float)): _error("unary - requires a number")
            return -v
