KEYWORDS = set("SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER LIMIT OFFSET AS ASC DESC AND OR NOT IN BETWEEN LIKE IS NULL TRUE FALSE".split())


def _tokenize(sql):
    ts, i, n = [], 0, len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1; continue
        start = i
        if c == '"':
            i += 1; chars = []
            while i < n:
                if sql[i] == '"':
                    if i + 1 < n and sql[i + 1] == '"': chars.append('"'); i += 2; continue
                    i += 1; break
                chars.append(sql[i]); i += 1
            else: raise ParseError("unterminated quoted name")
            ts.append(Token("NAME", "".join(chars), start, i, True)); continue
        if c == "'":
            i += 1; chars = []
            while i < n:
                if sql[i] == "'":
                    if i + 1 < n and sql[i + 1] == "'": chars.append("'"); i += 2; continue
                    i += 1; break
                chars.append(sql[i]); i += 1
            else: raise ParseError("unterminated string literal")
            ts.append(Token("STRING", "".join(chars), start, i)); continue
        if c.isalpha() or c == "_":
            i += 1
            while i < n and (sql[i].isalnum() or sql[i] == "_"): i += 1
            v = sql[start:i]; ts.append(Token("KW" if v.upper() in KEYWORDS else "NAME", v, start, i)); continue
        if c.isdigit() or (c == "." and i + 1 < n and sql[i+1].isdigit()):
            i += 1
            while i < n and sql[i].isdigit(): i += 1
            dec = False
            if i < n and sql[i] == ".":
                dec = True; i += 1
                while i < n and sql[i].isdigit(): i += 1
            raw = sql[start:i]; ts.append(Token("NUMBER", float(raw) if dec else int(raw), start, i)); continue
        op = sql[i:i+2]
        if op in ("<=", ">=", "!=", "<>", "||"):
            ts.append(Token("OP", op, i, i+2)); i += 2; continue
        if c in "=<>+-*/": ts.append(Token("OP", c, i, i+1)); i += 1; continue
        if c in "(),;": ts.append(Token(c, c, i, i+1)); i += 1; continue
        raise ParseError("unexpected character %r at position %d" % (c, i))
    ts.append(Token("EOF", None, n, n)); return ts


